"""Render INDEX.md: a generated overview of every skill."""

from __future__ import annotations

import os
from pathlib import Path

from .skill import Skill

HEADER = """\
# Skill index

<!-- Generated by `skillcheck index`. Do not edit by hand. -->

{counted}. This file is generated: run `skillcheck index` after changing a skill, and CI
fails (`skillcheck index --check`) if it is stale.
"""


def _cell(text: str) -> str:
    return text.replace("|", "\\|")


def _link(skill: Skill, base: Path) -> str:
    rel = os.path.relpath(skill.path.resolve(), base.resolve()).replace(os.sep, "/")
    return f"[`{skill.name}`]({rel})"


def render_index(skills: list[Skill], base: Path) -> str:
    """Render the index for ``skills``; links are relative to the directory ``base``."""
    ordered = sorted(skills, key=lambda s: s.name)
    counted = f"{len(ordered)} skill" + ("" if len(ordered) == 1 else "s")
    out = [HEADER.format(counted=counted)]
    out.append("| Skill | Purpose |")
    out.append("|---|---|")
    for skill in ordered:
        out.append(f"| {_link(skill, base)} | {_cell(skill.summary)} |")
    out.append("")
    out.append("## When each skill applies")
    for skill in ordered:
        out.append("")
        out.append(f"### `{skill.name}`")
        out.append("")
        out.append(" ".join(skill.description.split()))
    return "\n".join(out) + "\n"


def usable(skill: Skill) -> bool:
    """True when the skill has what the index needs: a name, a description and a purpose."""
    return bool(skill.name and skill.description and skill.summary)
